installer-gui-script.script:
function checkSetup() {
  if (system.files.fileExistsAtPath('/Library/Application Support/Rollo USB Pacing/recovery.json')) {
    my.result.type = 'Fatal';
    my.result.title = 'Rollo setup needs attention';
    my.result.message = 'A previous setup was interrupted. Stop sending labels and ask your administrator to follow the recovery guide before reinstalling.';
    return false;
  }
  if (!system.files.fileExistsAtPath('/Library/Printers/Rollo/rastertorollo')) {
    my.result.type = 'Fatal';
    my.result.title = 'Rollo setup needs attention';
    my.result.message = 'Install the official Rollo USB driver for macOS, then add the USB printer in System Settings > Printers & Scanners. Reopen this installer when that is done.';
    return false;
  }
  return true;
}
